SET NOCOUNT ON;
EXEC(N'CREATE OR ALTER TRIGGER dbo.TRG_MicroEquipmentActivities_MicroScope ON dbo.MicroEquipmentActivities AFTER INSERT, UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN dbo.LabEquipment e ON e.EquipmentID=i.EquipmentID WHERE e.EquipmentID IS NULL OR LEN(e.EquipmentCode)<>10 OR e.EquipmentCode NOT LIKE N''MIC-EQ-[0-9][0-9][0-9]'' OR TRY_CONVERT(int,SUBSTRING(e.EquipmentCode,8,3)) IS NULL OR TRY_CONVERT(int,SUBSTRING(e.EquipmentCode,8,3))<1 OR UPPER(LTRIM(RTRIM(COALESCE(e.Department,N''''))))<>N''MICROBIOLOGY'' OR e.IsActive<>1) THROW 56504, ''Only registered microbiology equipment may be recorded.'', 1; END;');
